// Peaceful world and natural history. Retire old war items without shifting saved question IDs.
const HISTORY_RETIRED=new Set();
const HISTORY_WAR_WORDS=/\b(wars?|world war|battles?|military|soldiers?|armies|army|anzac|invasions?|nazi|holocaust|weapons?|conquests?)\b/i;
BANK.history.forEach((q,i)=>{if(HISTORY_WAR_WORDS.test([q[0],...q[1],q[3]].join(' ')))HISTORY_RETIRED.add(i)});
